INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(4742, 'koKR', 'Pieczęć Wniebowstąpienia', 'Jak widzisz, nieozdobiona pieczęć ma trzy puste gniazda. Każde z nich trzeba wypełnić klejnotem symbolizującym władzę dowódców. Na koniec Nadrządca Wyrmthalak, pan dolnej cytadeli, musi wykuć pieczęć w płomieniach Czarnego Stada.$B$BZrozum jedno, śmiertelna istoto: rzadko się zdarza, by któryś z trzech generałów dolnej cytadeli akurat nosił przy sobie klejnot. Musisz zachować czujność. Nie trać determinacji!', 'Znajdź trzy klejnoty dowodzenia: Klejnot Tlącego Ciernia, Klejnot Iglicowego Kamienia i Klejnot Krwawego Topora. Przynieś je Vaelanowi razem z Nieozdobioną Pieczęcią Wniebowstąpienia.$B$BGenerałowie, o których mówił ci Vaelan, to: Mistrz Wojenny Wun z Tlącego Ciernia, Nadzorca Omokk z Iglicowego Kamienia i Nadrządca Wyrmthalak z Krwawego Topora.', '', 'Wróć do Vaelana w Iglicy Czarnej Góry.', '', '', '', '', 0),
(4743, 'koKR', 'Pieczęć Wniebowstąpienia', 'Poza mieszkańcami górnej cytadeli niewielu czarnych drakanów potrafi wykuć pieczęć własnym ognistym oddechem. Wyrmthalak jest jednym z nich, lecz jego woli nie da się złamać.$B$BMusisz udać się na Żmijowe Trzęsawisko na Pyłowym Bagnisku. Znajdziesz tam starożytnego smoka zwanego Emberstrife. Musisz złamać jego wolę, $N. Złam ją i użyj tej kuli na osłabionej bestii. Będziesz mieć zaledwie kilka sekund, by zawładnąć jego umysłem i rozniecić płomienie, które wykują pieczęć.', 'Udaj się na Żmijowe Trzęsawisko na Pyłowym Bagnisku. Znajdź starożytnego smoka Emberstrife\'a i bij go bez litości, aż jego wola zostanie złamana.$B$BW tej właśnie chwili musisz położyć Niewykutą Pieczęć Wniebowstąpienia przed wielką bestią. Potem szybko użyj Kuli smoczej energii na osłabionym smoku i przejmij władzę nad jego umysłem. Zapanuj nad bestią i zmuś ją, by zionęła Płomieniami Czarnego Stada na Niewykutą Pieczęć Wniebowstąpienia!', '', 'Wróć do Vaelana w Iglicy Czarnej Góry.', '', '', '', '', 0),
(4867, 'koKR', 'Urok Zgubowyj', 'Argh! Tak trudno mówić!$B$BWeź ten list! Przynieś moje mojo!', 'Przeczytaj Zwój Warosha. Przynieś Mojo Warosha Waroshowi.', '', 'Wróć do Warosha w Ruinach Alterak w Górach Alterak.', '', '', '', '', 0),
(4982, 'koKR', 'Rzeczy Bijou', 'Nocą, kiedy to miejsce jest słabo strzeżone, przemykam po mieście, robię notatki i zapisuję wszystko, co może mieć wartość strategiczną dla S.E.K.$B$BJednak zeszłej nocy wszystko poszło fatalnie. Potknęłam się o linkę i uruchomiłam alarm. Ukryłam sprzęt zwiadowczy i uciekłam w bezpieczne miejsce! Niestety nie mogę się do niego dostać. Podwoili, a nawet potroili patrole! Wszystkie te informacje przepadły.$B$BOdzyskaj moje rzeczy, a grzecznie wrócę do S.E.K.', 'Znajdź Rzeczy Bijou i oddaj je właścicielce. Pamiętasz, że wspominała, iż ukryła je na najniższym poziomie miasta.$B', '', 'Wróć do Bijou w Górach Alterak.', '', '', '', '', 0),
(5001, 'koKR', 'Rzeczy Bijou', 'Zwykle nie zadaję się z takimi jak ty, ale wygląda na to, że utknęłam między trollem a kowadłem. Widzisz, moja misja jest dla Hordy niezwykle ważna. Jednak informacje, które zdobyłam, dotyczą również bezpieczeństwa Przymierza. Uwierz mi, nie sympatyzuję z Przymierzem, ale zagrożenie ze strony Czarnej Skały to coś więcej niż tylko banda orków.$B$BPomożesz mi odnaleźć moje rzeczy, a ja pomogę tobie informacjami, które mogą się przydać twoim pobratymcom.$B$BUmowa stoi?', 'Znajdź Rzeczy Bijou i oddaj je właścicielce. Powodzenia!$B', '', 'Wróć do Bijou w Górach Alterak.', '', '', '', '', 0),
(6502, 'koKR', 'Amulet smoczego ognia', 'To część smoka – łuska zaklęta i przemieniona. W całości mogłaby zapewnić dostęp do leża bestii. Rozbita jest bezużyteczna.$B$BMożna ją naprawić, lecz potrzeba do tego krwi czempiona czarnych smoków. Jest taki jeden... Nazywają go generałem Drakkisatem, władcą armii smoczych pomiotów Nefariana. Być może $gsłyszałeś:słyszałaś; o nim?$B$BWróć z jego krwią, a zaczaruję ten fragment tak, że da ci dostęp do Leża Onyxii.', 'Musisz zdobyć Krew czempiona czarnych smoków od generała Drakkisata. Drakkisat przebywa w swojej sali tronowej za Salami Wniebowstąpienia w Iglicy Czarnej Góry.', '', 'Wróć do Haleh w Ruinach Kel\'Theril w Zimozdroju.', '', '', '', '', 0),
(7761, 'koKR', 'Rozkaz Czarnorękiego', 'Imbecylu,$B$Bmam bardzo niewielką wiarę w to, że zdołasz powstrzymać obcych przed dostaniem się do leża pana. Na wypadek, bardzo prawdopodobny, twojej śmierci ta kula ma wbudowane zabezpieczenie, które nie pozwoli obcym teleportować się prosto do Leża Czarnoskrzydłego.$B$BZ kuli mogą korzystać tylko ci, którym wypalono na dłoni Znak Drakkisata. Na szczęście Drakkisat nie jest nawet w połowie tak niekompetentny jak ty, kwatermistrzu. Sam pilnuje piętna!$B$B– Wódz Wojenny Rwij Czarnoręki$B$BPS Zniszcz ten list, idioto.', 'Co za głupi ork. Wygląda na to, że musisz znaleźć to piętno i zdobyć Znak Drakkisata, aby skorzystać z Kuli dowodzenia.$B$BZ listu wynika, że piętna strzeże generał Drakkisat. Może warto to sprawdzić.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(4742, 'koKR', '<Postać Vaelana na chwilę się rozmywa.>$B$B<Zebrane przez ciebie elementy zniknęły.>$B$BNiewykuta Pieczęć Wniebowstąpienia jest gotowa. Czas na ostatni krok.', 0),
(4743, 'koKR', 'Stój spokojnie, a ja rzucę ostatnią inwokację ochronną.$B$B<Oczy Vaelana zmieniają się w dwie kule ognia.>$B$BPieczęć Wniebowstąpienia jest gotowa...$B$BWiedz, że nasyciłem ten artefakt potężnymi zaklęciami ochronnymi. W najczarniejszej godzinie, gdy wszystko będzie się wydawać stracone, moc Czerwonego Stada będzie do twojej dyspozycji.', 0),
(4867, 'koKR', 'Aha! Już czuję, jak wraca moja moc. A mój umysł nie jest już dręczony klątwą Uroka.$b$bDziękuję, $N! Pokora nie leży w mojej naturze, ale muszę przyznać, że mi $gpomogłeś:pomogłaś;.$b$bŻyczę ci szczęścia w wędrówce przez Iglicę Czarnej Góry. Głupiec z ciebie, jeśli myślisz, że dotrzesz na sam szczyt, ale twojej odwagi nikt nie może podważyć.', 0),
(4982, 'koKR', 'Udało ci się! Kiedy Lexlort dostanie te plany, zapomni o wszystkich paskudnych rzeczach, które chciał mi zrobić.$B$B$N, jesteś $gmoim bohaterem:moją bohaterką;!', 0),
(5001, 'koKR', 'No proszę! Gdzie one były??', 0),
(6502, 'koKR', 'Ten amulet zapewni ci dostęp, którego szukasz. Leże Onyxii znajduje się na Pyłowym Bagnisku. Dopóki masz przy sobie amulet, jej zabezpieczenia nie zdołają cię powstrzymać.$B$BBłękitne Stado życzy ci powodzenia, $N.', 0),
(7761, 'koKR', 'Nawet nie drgniesz, gdy tlące się piętno wżera się w twoje ciało. Ale z ciebie twardziel!$B$BMasz teraz Znak Drakkisata. Miłej zabawy przy szturmowaniu zamku.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(4742, 'koKR', 'Odwaga i cierpliwość ponad wszystko, $N!', 0),
(4743, 'koKR', 'Nie trać czasu, $N. Nefarian gorączkowo pracuje nad tym, by rozpętać swoje zło na naszym świecie.', 0),
(4867, 'koKR', 'Ach! Masz moje mojo?', 0),
(6502, 'koKR', 'Czas płynie bez przerwy i nie zwalnia. Moje życie jest wieczne, lecz twoje nie. Nie marnuj czasu, który ci pozostał...', 0);
