(16244, 'koKR', 'Formuła: zaklęcie rękawic – większa siła', 'Uczy trwałego zaklinania rękawic, co zwiększa siłę o 7.', 0),
(16247, 'koKR', 'Formuła: zaklęcie broni dwuręcznej – znakomity impet', 'Uczy trwałego zaklinania dwuręcznej broni do walki wręcz, co zwiększa jej obrażenia o 9.', 0),
(16250, 'koKR', 'Formuła: zaklęcie broni – znakomite uderzenie', 'Uczy trwałego zaklinania broni do walki wręcz, co zwiększa jej obrażenia o 5.', 0),
(18047, 'koKR', 'Ogniste stąpaki', '', 0),
(18048, 'koKR', 'Młot mistrza kowalskiego', '', 0),
(18779, 'koKR', 'Dolna połowa księgi „Zaawansowane płatnerstwo: tom I”', '', 0),
(19227, 'koKR', 'As bestii', '', 0),
(21955, 'koKR', 'Projekt: krab z czarnego diamentu', 'Uczy wytwarzania kraba z czarnego diamentu.', 0),
(23320, 'koKR', 'Tablica: Wstrząs płomieni VI', 'Uczy czaru: Wstrząs płomieni (ranga 6).', 0),
(24101, 'koKR', 'Księga: Zajadłe ugryzienie V', 'Uczy czaru: Zajadłe ugryzienie (ranga 5).', 0),
(24102, 'koKR', 'Podręcznik: Wypatroszenie IX', 'Uczy czaru: Wypatroszenie (ranga 9).', 0),
