INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2212, 'koKR', '„Och, jestem przeklęty! Byłem niegdyś wielkim ogrzym magiem klanu Iglicowego Kamienia, lecz wyzwałem Uroka Zgubowyja, a on odebrał mi magię i rzucił na mnie klątwę. Teraz muszę przemierzać korytarze Hordemaru jako ta nędzna kreatura!$B$BPomóż mi! Stań do walki z Urokiem i odbierz mu moją magię! Nie będzie łatwo, bo Urok kryje się w cieniu i można go przywołać tylko wielkim wyzwaniem.$B$BTym wyzwaniem będzie śmierć jego najbardziej zaufanego pomocnika, Nadzorcy Omokka.$B$BCzytaj dalej, a zrozumiesz.”', 0),
(2213, 'koKR', '„Nadzorca Omokk rządzi klanem Iglicowego Kamienia, ale czyni to dzięki magii Uroka. Urok zauroczył Omokka zaklęciem, które potrafi uśmiercić każdego ogra, który rzuci mu wyzwanie. Użył tego zaklęcia wiele razy, a czaszki swoich ofiar trzyma na stosie w miejscu mocy nad komnatą Omokka.$B$BTam musisz się udać, by stanąć do walki z Urokiem.”', 0),
(2214, 'koKR', '„Znajdź nierówną pikę w obozach Blizny Tarczy. Często ustawiają je przy swoich posłaniach, niedaleko wejścia do domeny ogrów Iglicowego Kamienia.$B$BGdy zdobędziesz pikę, przebij się do Nadzorcy Omokka. Zabij go i zatknij jego głowę na pice.$B$BWtedy będziesz $ggotów:gotowa; na prawdziwe wyzwanie.”', 0),
(2215, 'koKR', '„Udaj się do miejsca mocy nad domeną Iglicowego Kamienia, za Tunelami Pajęczej Sieci. Leżą tam stosy czaszek wrogów i rywali Uroka. To właśnie tam musisz wbić pikę z głową Omokka!$B$BGdy głowa znajdzie się na miejscu, Urok na pewno przybędzie... ale najpierw naśle na ciebie swoje sługi. Pokonaj je, a w końcu przywołasz samego Uroka.$B$BZabij Uroka i odzyskaj moją magię. Gdy odzyskam moc, wynagrodzę cię.”', 0),
(2216, 'koKR', '„Powodzenia. A oto wskazówka, która może ci pomóc w walce ze sługami Uroka:$B$BZaklęcie, którego Omokk używa przeciw ogrom – to, które je uśmierca – może zachować moc nawet po śmierci Omokka. Podczas walki ze sługami Uroka przywołaj moc zaklętą w głowie Omokka – przy odrobinie szczęścia Omokk powali sługi Uroka!$B$BCóż za trafna ironia.”', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(10162, 14, 0, 'koKR', 'Ach... bohaterowie. Uparci jesteście, co? Wasz sojusznik próbował zmierzyć swoją moc z moją i zapłacił za to. Teraz będzie mi służył... zarzynając was. Wstawaj, mały czerwony żmiju... i zniszcz ich!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(5268, 'koKR', 'Ha! Ha! Ha! Dzięki za uwolnienie, głupcy. Pozwólcie, że się odwdzięczę, spalając wam ciało do kości.', '', 0),
(5555, 'koKR', 'Nareszcie – jedno z was jest godne mojej wiedzy. Nie lękaj się – zbadałem twoje myśli, nic złego cię nie spotka.', '', 0),
(5556, 'koKR', 'Słuchaj uważnie, bo jeśli nie będziesz $gprzygotowany:przygotowana;, władca Czarnej Góry z pewnością cię zniszczy.', '', 0),
(5565, 'koKR', '%s zaczyna odzyskiwać siły!', '', 0),
(5566, 'koKR', '%s niemal w pełni odzyskuje siły!', '', 0),
(5567, 'koKR', '%s odzyskuje moc i zrywa więzy!', '', 0),
(5568, 'koKR', 'Przed dziesięcioleciami – w czasach dawnych już wojen i konfliktów – nasz ród został zepchnięty na skraj zagłady. Wiele przetrwaliśmy.$B$BNawałę Płonącego Legionu. Duszę Demona. Rozłam między Aspektami. Wyniesienie Śmiercioskrzydłego. Zniewolenie naszej królowej, Alexstrazy, przez Smocze Paszcze.$B$BPrzez to wszystko byliśmy niezłomną wolą smoków – nieustraszoną siłą, która walczyła o to, by nasz gasnący ród miał jeszcze swoje miejsce na tym świecie.', '', 0),
(5569, 'koKR', 'Wasz ród?', 'Wasz ród?', 0),
(5570, 'koKR', 'W rzeczy samej. Stoję przed tobą w postaci, którą jesteś w stanie pojąć, śmiertelna istoto. Z pewnością nie $gzniósłbyś:zniosłabyś; obecności smoka znanego jako Vaelastraz.$B$B<Vaelan się śmieje.>$B$BMam mówić dalej?', '', 0),
(5571, 'koKR', 'Proszę.', 'Proszę.', 0),
(5572, 'koKR', 'Może powinienem ci wyjaśnić, dlaczego tu jestem.$B$BCzy wiesz coś o Aspekcie Śmiercioskrzydłym? Albo o jego potomstwie, Nefarianie i Onyxii?', '', 0),
(5573, 'koKR', 'Nie, Vaelanie, nie wiem.\n', 'Nie, Vaelanie, nie wiem.\n', 0),
(5574, 'koKR', 'Śmiercioskrzydły, niegdyś znany jako Neltharion, był Aspektem ucieleśniającym siłę świata – tytan kształtujący Khaz\'goroth, Kowal świata, obdarzył go niemal nieograniczoną władzą nad tym śmiertelnym królestwem.$B$BZdradą i podstępem plugawiec przekonał pozostałe cztery Aspekty, by nasyciły swoją mocą przedmiot zwany Duszą Demona. Bardzo je to osłabiło i doprowadziło do rozłamu między niegdyś wielkimi Aspektami.\n', '', 0),
(5575, 'koKR', 'Dusza Demona?', 'Dusza Demona?', 0),
(5576, 'koKR', 'W rzeczy samej. Przedmiot ostatecznie zniszczono, a Śmiercioskrzydły omal nie zginął, pokonany połączoną i odnowioną mocą czterech pozostałych Aspektów. Nie wiadomo, gdzie jest teraz. Wiemy jednak, że jeden z jego potomków, Nefarian, włada tą cytadelą i pragnie dokończyć dzieło ojca.', '', 0),
(5577, 'koKR', 'Dokończyć dzieło?', 'Dokończyć dzieło?', 0),
(5578, 'koKR', 'Przed wygnaniem Śmiercioskrzydły próbował stworzyć nieczyste potomstwo. Mieszańce, które nie tylko byłyby odporne na wrodzone, naturalne moce i zdolności swoich Aspektów, ale też całkowicie podległe Śmiercioskrzydłemu.$B$BWygląda na to, że tam, gdzie ojciec poniósł porażkę, Nefarianowi mogło się udać – przynajmniej częściowo.$B$BTo Ysera, Aspekt Snów, ujrzała te plugastwa i zmusiła nas do działania. Jeśli te „chromatyczne” smoki istnieją, trzeba je zniszczyć.', '', 0),
(5579, 'koKR', 'Czemu nie zniszczyć ich połączoną mocą Aspektów?', 'Czemu nie zniszczyć ich połączoną mocą Aspektów?', 0),
(5580, 'koKR', 'To nie nasza droga i nie byłoby to możliwe. Nefariana strzegą starożytne osłony, stare jak same Aspekty. To one nie pozwalają mi wejść do wewnętrznego sanktuarium tej cytadeli. Mroczna magia nie wpuści nikogo z innych stad bez namaszczenia... chyba że.', '', 0),
(5581, 'koKR', 'Chyba że?', 'Chyba że?', 0),
(5582, 'koKR', 'Ktoś, kto nie jest smokiem, może zdobyć Ozdobioną Pieczęć Wniebowstąpienia i przejść przez chronioną barierę. Mnie posiadanie takiego przedmiotu z pewnością by zniszczyło, ale ty być może zdołasz go użyć i opuścić barierę.\n', '', 0),
(5583, 'koKR', 'Chętnie spróbuję, ale będę potrzebować wskazówek.', 'Chętnie spróbuję, ale będę potrzebować wskazówek.', 0),
(5584, 'koKR', 'Musisz znaleźć wśród nędzników z dolnej części tej cytadeli kogoś, kto zdobył Nieozdobioną Pieczęć Wniebowstąpienia. Dla pośledniejszych istot zdobycie tego przedmiotu to wielki zaszczyt – to pierwszy krok do wstępu do górnej cytadeli i dołączenia do elitarnej straży Nefariana, Legionu Czarnorękiego. Znajdź taki przedmiot i przynieś mi go, abym mógł zbadać jego właściwości. Gdy skończę badać pieczęć, będę wiedział, co dalej.', '', 0),
(5585, 'koKR', 'Zrobię, co w mojej mocy, Vaelanie.', 'Zrobię, co w mojej mocy, Vaelanie.', 0),
(5586, 'koKR', 'Ostrzegam cię, śmiertelna istoto: niezwykle rzadko któryś z pośledniejszych klanów tej cytadeli ma przy sobie taki przedmiot. Poszukiwania mogą potrwać dziesięciolecia. Radzę ci tępić te bestie bez litości.', '', 0),
(5587, 'koKR', 'Tak się stanie.', 'Tak się stanie.', 0),
(5588, 'koKR', 'Nie podchodź z nią bliżej, śmiertelna istoto. Już stąd wyczuwam zło krążące w tej pieczęci.$B$BDaj mi chwilę na zbadanie przedmiotu – trzymaj go mocno.', '', 0),
(5589, 'koKR', 'Jak sobie życzysz, Vaelanie.', 'Jak sobie życzysz, Vaelanie.', 0),
(5590, 'koKR', '%s otacza bariera antymagii.', '', 0),
(5591, 'koKR', 'Odkryłem ścieżkę, którą musisz podążyć. Czy jesteś $ggotów:gotowa;?', '', 0),
(5592, 'koKR', 'Precz, śmiertelna istoto. Nie jesteś $ggodzien:godna; mojej wiedzy.', '', 0),
(5596, 'koKR', 'Dość! Koniec zabawy!', '', 0),
(5611, 'koKR', '', '%s zaczyna przyzywać Tkacza grozy Czarnorękiego!', 0),
(5613, 'koKR', '', '%s zaczyna przyzywać Weterana Czarnorękiego!', 0),
(5622, 'koKR', 'Jesteśmy zgubieni!', 'Jesteśmy zgubieni!', 0),
(5635, 'koKR', 'Doskonale... Wygląda na to, że natrętne insekty zjawiły się w samą porę, by nakarmić mój legion. Witajcie, śmiertelnicy!', '', 0),
(5640, 'koKR', 'Niech na piasku areny nie zostanie ani kropla ich krwi, moje dzieci. Ucztujcie na ich duszach!', '', 0),
(5664, 'koKR', 'Użyj mroźnego oddechu, imbecylu!', '', 0),
(5665, 'koKR', 'Głupcy... Zabijcie tego w sukience!', '', 0),
(5667, 'koKR', 'Nie zmuszajcie mnie, dzieci! Waszymi skórami wyłożę sobie buty.', '', 0),
(5668, 'koKR', 'Wasze wysiłki pójdą na marne. Nikt nie stanie nam na drodze!', '', 0),
(5709, 'koKR', 'TO NIEMOŻLIWE!!! Rwiju, zajmij się tymi insektami.', '', 0),
(5710, 'koKR', 'Śmiertelnicy polegli! Nadchodzi nowa era legionu Czarnej Skały!', '', 0),
(5711, 'koKR', '%s spada ze swojego smoka!', '', 0),
(5720, 'koKR', 'Wódz Wojenny szybko się z wami rozprawi, śmiertelnicy. Szykujcie się!', '', 0),
(5722, 'koKR', 'Z przyjemnością...', '', 0),
(5726, 'koKR', 'Posmakujcie mojej mocy!', '', 0),
(5776, 'koKR', 'Vaelastrazie, gdy ten świat będzie należał do Czarnego Stada, twoje stado dozna kresu.', '', 0),
(5777, 'koKR', 'Ale na razie musi wystarczyć twoja śmierć...', '', 0),
(5824, 'koKR', 'Wasze zwycięstwo będzie krótkotrwałe. Dni zarówno Przymierza, jak i Hordy dobiegają końca! Nasze następne spotkanie będzie ostatnim.', '', 0),
(9846, 'koKR', 'Spodziewasz się, że ulęknę się twojego potężnego legionu, $n?$B$BJesteś dla mnie niczym. Mniej niż niczym. Gdybym chciał twojej głowy, podano by mi ją na pice.$B$BPopełniasz błąd, który popełniają wszyscy śmiertelnicy.$B$B<Lord Victor Nefarius wzdycha.>$B$BCzas robi dziwne rzeczy z tymi, którzy używają go jak waluty.\n', '', 0),
(9902, 'koKR', 'Nie $gpopełniłem:popełniłam; żadnych błędów.', 'Nie $gpopełniłem:popełniłam; żadnych błędów.', 0),
(9903, 'koKR', 'W pogoni za chwałą $gzałożyłeś:założyłaś;, że tempo tej gry wyznaczają twoje czyny. Czy w ogóle pojmujesz, jak niedorzecznie brzmi to dla istoty takiej jak ja? Istoty, która gdyby tylko zechciała, sprawiłaby, że twoje własne nędzne myśli zgniotą tę wielkości orzeszka ziemnego bryłkę szarej masy pływającą w twojej czaszce.\n', '', 0),
(9904, 'koKR', 'Postradałeś zmysły, Nefariusie. Mówisz zagadkami.', 'Postradałeś zmysły, Nefariusie. Mówisz zagadkami.', 0),
(9907, 'koKR', 'W tym świecie czas jest twoim wrogiem, a moim największym sprzymierzeńcem. Ta wielka gra zwana życiem, w którą sądzisz, że grasz, w rzeczywistości gra tobą. Na co odpowiadam...', '', 0),
(14502, 'koKR', '%s parska.', '', 0),
(21235, 'koKR', 'Niewyobrażalne!', '', 0),
(25783, 'koKR', '%s burczy.', '', 0),
(29772, 'koKR', '%s płacze.', '', 0),
(35709, 'koKR', 'Niech rozpoczną się igrzyska!', '', 0),
(38661, 'koKR', 'Niemożliwe!', '', 0);
